fun HomeScreen(
 seccionSeleccionada: Int,
 onSeleccionar: (Int) -> Unit,
 contenido: @Composable (PaddingValues) -> Unit
) {
 Scaffold(
 bottomBar = {
 NavigationBar {
 NavigationBarItem(
 selected = seccionSeleccionada == 0,
